-- DROP FUNCTION dash360.clearing_instruction_create(int4, bpchar, int4, bpchar, varchar);

CREATE OR REPLACE FUNCTION dash360.clearing_instruction_create(in_date_id integer, in_clearing_status character,
                                                               in_user_id integer, in_modification_type character,
                                                               in_json_values character varying)
    RETURNS TABLE
            (
                trade_json    character varying[],
                clearing_json character varying[]
            )
    LANGUAGE plpgsql
    COST 1
AS
$function$
-- AK 20231129 : https://dashfinancial.atlassian.net/browse/D360-12491 added cboe_reason_code field to insert into genesis2.clearing_instruction_entry
-- PD 20240530 : https://dashfinancial.atlassian.net/browse/DS-8362 added box_additional_client_memo field to insert statement
-- OS 20241202 https://dashfinancial.atlassian.net/browse/DS-9047 added blaze_account_alias to output
-- OS 20250129 https://dashfinancial.atlassian.net/browse/DS-9502 add logging
declare

    l_clearing_instr_id       int;
    l_clearing_instr_entry_id int;
    trade_json                varchar[];
    clearing_json             varchar[];
    l_msg_text                text;
    l_load_id                 int;
    l_step_id                 int;
    l_row_cnt                 int4;

begin
    l_msg_text := 'clearing_instruction_create for ' || in_date_id::text || ', clearing status: ' || in_clearing_status ||
                  ', user_id: ' || in_user_id::text || ', modification_type: ' || in_modification_type ||'. ';

    select nextval('public.load_timing_seq') into l_load_id;
    l_step_id := 1;
    select public.load_log(l_load_id, l_step_id, l_msg_text || '  STARTED ====', 0, 'O')
    into l_step_id;

    --VP 20230914 https://dashfinancial.atlassian.net/browse/DS-7245
--insert into clearing_instruction
    insert into genesis2.clearing_instruction
    (clearing_instr_id, date_id, status, created_by_user_id, modification_type)
    values (nextval('clearing_instruction_clearing_instr_id_seq'::regclass), in_date_id, in_clearing_status, in_user_id,
            in_modification_type)
    returning clearing_instr_id into l_clearing_instr_id;
    get diagnostics l_row_cnt = row_count;

    select public.load_log(l_load_id, l_step_id, l_msg_text || '  Step 1 - insert into genesis2.clearing_instruction',
                           l_row_cnt, 'I')
    into l_step_id;
    /*INSERT INTO genesis2.clearing_instruction_entry
    (clearing_instr_entry_id, date_id, clearing_instr_id, trade_record_id, account_id, opt_customer_firm, open_close, last_qty, last_px, exec_broker, cmta, clearing_account_number, sub_account, remarks, trade_record_time, street_exec_broker, client_commission_rate, branch_sequence_number, trade_text, frequent_trader_id)
    VALUES(nextval('clearing_instruction_clearing_instr_entry_id_seq'::regclass), in_date_id, l_clearing_instr_id, @TradeRecordId, @AccountId, @Capacity, @OpenClose, @LastQty, @LastPx, @ExecBroker, @CMTA, @ClearingAccountNumber, @SubAccount, @Remarks, @TradeRecordTime, @StreetExecBroker, @CommissionRate, @BranchSeqNbr, @TradeText, @FrequentTraderId)
    returning clearing_instr_entry_id;*/

--insert into clearing_instruction_entry (most of values are from input param in_json_values)
    with ct as (select in_json_values::json as jsn),
         trd_ids as (select json_object_keys(jsn) as old_trade_record_id
                     from ct),
         tr_values as (select trd_ids.old_trade_record_id,
                              ct.jsn -> trd_ids.old_trade_record_id val_arr
                       from ct,
                            trd_ids)
    insert
    into genesis2.clearing_instruction_entry (clearing_instr_entry_id, date_id, clearing_instr_id, new_trade_record_id,
                                              trade_record_id, account_id, opt_customer_firm, open_close, last_qty,
                                              last_px, exec_broker, cmta, clearing_account_number,
                                              trade_liquidity_indicator, sub_account, remarks, trade_record_time,
                                              electronic_report_status, street_account_name, street_exec_broker,
                                              client_commission_rate, trade_text, branch_sequence_number,
                                              frequent_trader_id, box_additional_firm, electronic_report_error_text,
                                              cboe_reason_code, box_additional_client_memo, blaze_account_alias)
    select nextval('clearing_instruction_clearing_instr_entry_id_seq'::regclass),
           in_date_id,
           l_clearing_instr_id,
           (l.value ->> 'new_trade_record_id')::bigint,
           tr_values.old_trade_record_id::bigint,
           (l.value ->> 'account_id')::int,
           (l.value ->> 'opt_customer_firm')::bpchar,
           (l.value ->> 'open_close')::bpchar,
           (l.value ->> 'last_qty')::int,
           (l.value ->> 'last_px')::numeric,
           (l.value ->> 'exec_broker')::varchar,
           (l.value ->> 'cmta')::varchar,
           (l.value ->> 'clearing_account_number')::varchar,
           (l.value ->> 'trade_liquidity_indicator')::varchar,
           (l.value ->> 'sub_account')::varchar,
           (l.value ->> 'remarks')::varchar,
           (l.value ->> 'trade_record_time')::timestamp,
           (l.value ->> 'electronic_report_time')::varchar,
           (l.value ->> 'street_account_name')::varchar,
           (l.value ->> 'street_exec_broker')::varchar,
           (l.value ->> 'client_commission_rate')::numeric,
           (l.value ->> 'trade_text')::varchar,
           (l.value ->> 'branch_sequence_number')::varchar,
           (l.value ->> 'frequent_trader_id')::varchar,
           (l.value ->> 'box_additional_firm')::varchar,
           (l.value ->> 'electronic_report_error_text')::varchar,
           (l.value ->> 'cboe_reason_code')::varchar as r,
           (l.value ->> 'box_additional_client_memo')::varchar,
           l.value ->> 'blaze_account_alias'
    from tr_values,
         json_array_elements(tr_values.val_arr) l;
    get diagnostics l_row_cnt = row_count;

    select public.load_log(l_load_id, l_step_id,
                           l_msg_text || '  Step 2 - insert into genesis2.clearing_instruction_entry', l_row_cnt, 'I')
    into l_step_id;

    select array_agg(row_to_json(cte))
    into trade_json
    from (select l_clearing_instr_id as clearing_instr_id, *
          from dash360.clearing_instruction_modifications(l_clearing_instr_id)) cte;

    select public.load_log(l_load_id, l_step_id, l_msg_text || '  Step 3 - clearing_instruction_modifications',
                           l_row_cnt, 'O')
    into l_step_id;

    select array_agg(row_to_json(cte))
    into clearing_json
    from (select *
          from dash360.clearing_get_change_requests(clearing_instruction_id=>l_clearing_instr_id)) cte;

    select public.load_log(l_load_id, l_step_id, l_msg_text || '  Step 4 - clearing_get_change_requests and COMPLETED ========', 0, 'O')
    into l_step_id;

    return query
        select trade_json, clearing_json;


end;
$function$
;


select substr(:in_date_id::text, 5,2)
create or replace function dash360.report_billing_taf_fee_calculation(in_start_date_id int4,
                                                                      in_end_date_id int4)
    returns table
            (
                ret_row text
            )
    language plpgsql
AS
$fn$
    -- 2025-01-30 OS https://dashfinancial.atlassian.net/browse/DEVREQ-5351
declare
    l_load_id int;
    l_step_id int;
    l_row_cnt int;
    l_list_1  text[] := '{aostb01, chapdel, deutsche, elevation, eroom01, ftrust, haywood01, meridian, ofp0055,
                 ofp0048, rwbaird01, srtamex, sunrise01, tdsec, tfsnova, triadsc01, coexparis, wexats}'::text[];;
    l_list_2  text[] := '{3ifund, 3ifund2, buckpac, caceisb01, ctcht, dftdesk04, dftdesk03, dashdesk,
                 dftdesk02, famco01, grponeht, hudson02, ionicap02, janestht, murchnsn2, opcoht,
                 peak6ht, sarasindf, schafer01, sfght, sgcap02, socgenlon, tornoht, ofp0132, wiltrht,
                 wolvrnht}'::text[];

begin
    select nextval('public.load_timing_seq') into l_load_id;
    l_step_id := 1;
    select public.load_log(l_load_id, l_step_id, 'report_billing_taf_fee_calculation for ' || in_start_date_id::text ||
                                                 '-' || in_end_date_id::text || ' STARTED ====', 0, 'O')
    into l_step_id;

    return query
        select array_to_string(ARRAY [
                                   substr(date_id::text, 1, 4), -- as year,
                                   substr(date_id::text, 5, 2), --as month,
                                   dtr.date_id::text,
                                   dtr.instrument_type_id,
                                   dtr.trading_firm_id,
                                   tf.trading_firm_name,
                                   tf.cat_crd,
                                   dtr.side,
--,array_agg(idl.imid) as cat_imids
                                   a.broker_dealer_mpid,
                                   a.is_broker_dealer,
                                   array_agg(distinct idl.finra_member)::text, --as cat_finra_member,
                                   array_agg(distinct idl.exchange_id)::text, --as cat_exchange_finra,
                                   array_agg(distinct idl.file_date_id)::text, --as cat_file_date_id,
                                   sum(dtr.last_qty)::text, --as last_qty,
--this case statement is used to hardcode firms that we know have the wrong is finra member  in this dataset
                                   case
                                       when lower(dtr.trading_firm_id) = any (:l_list_1)
                                           then '{Y}'::text
                                       when lower(dtr.trading_firm_id) = any (:l_list_2) then '{N}'::text
                                       else array_agg(distinct idl.finra_member)::text end, --as Corrected_Is_FINRA_Member
--designate trading firms with incorrect imid as finra members and therefore 0 fees
                                   case
                                       when lower(dtr.trading_firm_id) = any (:l_list_1)
                                           then 0::text
                                       -------------------------------------beginning of 2024 fees
                                       when dtr.date_id >= '20240101' and dtr.instrument_type_id = 'O'
                                           and lower(dtr.trading_firm_id) = any (:l_list_2)
                                           then (sum(dtr.last_qty) * .00279)::text
                                       when dtr.date_id >= '20240101' and dtr.instrument_type_id = 'E' and
                                            dtr.side <> '1'
                                           and lower(dtr.trading_firm_id) = any (:l_list_2)
                                           then (sum(dtr.last_qty) * .000166)::text
                                       --adjustment for trading firms using DFIN that are not FINRA BDs and should have fees assessed for 2023 equities
                                       when dtr.date_id >= '20240101' and dtr.instrument_type_id = 'O' and
                                            array_agg(distinct idl.finra_member) <> '{Y}' and dtr.side <> '1'
                                           then (sum(dtr.last_qty) * .00279)::text
--show the calculation for all equity trades. House DVP and client DVP charges will need to be replaced with allocation based calculations.
                                       when dtr.date_id >= '20240101' and dtr.instrument_type_id = 'E' and
                                            array_agg(distinct idl.finra_member) <> '{Y}' and dtr.side <> '1'
                                           then (sum(dtr.last_qty) * .000166)::text
                                       end --as Option_and_Equity_TAF_Charges
                                   ], ',', '')
        from billing.dash_trade_record dtr
                 left join genesis2.account a on dtr.account_id = a.account_id and a.is_deleted = 'N'
            --left outer join genesis2.genesis2.clearing_account ca      on dtr.account_id = ca.account_id and ca.is_deleted = 'N'
                 left join genesis2.trading_firm tf on dtr.trading_firm_id = tf.trading_firm_id
            --left outer join temp_cat on temp_cat.crdid = tf.cat_crd
                 left join lateral (select idl.crdid, idl.firm_name, idl.finra_member, idl.exchange_id, idl.file_date_id
                                    from external_data.imid_daily_list idl
                                    where tf.cat_crd = idl.crdid
                                      and idl.exchange_id = 'FINRA'
                                      and dtr.date_id >= idl.file_date_id
                                    order by idl.file_date_id desc
                                    limit 1
            )
            as idl on true

        where dtr.date_id between :in_start_date_id and :in_end_date_id
          and dtr.is_busted = 'N'
          and dtr.side <> '1'
          and dtr.subsystem_id not ilike all ('{LPEDW,LPEDW_DUPE,OMS_EDW%}')
          and dtr.fix_comp_id not ilike all ('{TRAFIXALGOINT_NY,TRAFIXCROSS_NY}')
          and dtr.symbol not ilike all ('{ASBAG,BJE,BKX,BKX,BTK,BYTX,CRX,CZH,DDX,DFI,DFX,DIVD,DJX,DRG,DXL,EPX,EWF,GUO,HGX,HKO,INDU,INDUDL,JBV,JLO,KBK,KIX,KRX,KSX,MID,MNX,MRUT,MSH,MXEA,MXEF,NANOS,NBI,NDX,NDX,NDXDL,NDXP,NDXQ,NDXW,
NDXX,NDXY,NQX,NQX,NYFANG,OEX,OEX,OEXM,OEXQ,OSX,OSX,PGG,QGRI,RAV,RIY,RLG,RLV,RMC,ROY,RRY,RTY,RUJ,RUO,RUT,RUTQ,RUTW,RUY,SIXB,SIXC,SIXE,SIXI,SIXM,SIXR,SIXRE,SIXT,SIXU,SIXV,SIXY,SML,SOX,SOX,SPIKE,SPX,SPX,SPXPM,SPXQ,SPXQ,
SPXW,UTY,UTY,VIX,VIXQ,VIXW,VOLQ,XAL,XAU,XAU,XBD,XCI,XEO,XEO,XEOQ,XMI,XND,XNDX,XSP,XSP,XSPQ}')
          and dtr.exchange_id not ilike all
              ('{BLAZE,TRAFX,C1PAR, PHLXFB, XCHI, BLAZEE,BRKPT, BRKPTE, SQHA, SQHT, JSEB, CTDL, BRKPT, AMXO}')
          and dtr.trading_firm_id not ilike 'RFABOXQOO'
        group by dtr.date_id
               , dtr.instrument_type_id
               , dtr.trading_firm_id
               , tf.trading_firm_name
               , tf.cat_crd
               , dtr.side
               , a.broker_dealer_mpid
               , a.is_broker_dealer;
    get diagnostics l_row_cnt = row_count;

    select public.load_log(l_load_id, l_step_id, 'report_billing_taf_fee_calculation for ' || in_start_date_id::text ||
                                                 '-' || in_end_date_id::text || ' STARTED ====', l_row_cnt, 'O')
    into l_step_id;
end;
$fn$;



create index if not exists imid_daily_list_crdid_exchange_id_idx on external_data.imid_daily_list (crdid,exchange_id);
select * from external_data.imid_daily_list